"""Local evidence sheets and report. Existing neighbouring boat files are read-only."""
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,hashlib
S=Path(__file__).resolve().parent;R=S.parents[3];O=R/'Art/Models/BoatsV2/JigBoatV1';P=O/'renders'
font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',23);small=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',17)
views=['side','top','front-three-quarter','back-three-quarter','deck-55','low-waterline','game-exact-45']
sheet=Image.new('RGB',(1500,1810),'#EDE7DC');d=ImageDraw.Draw(sheet);d.text((20,15),'JIG BOAT — exported FBX / authoring review, not Unity',font=font,fill='#173F57')
for i,name in enumerate(views):
 im=Image.open(P/(name+'.png'));assert im.size==(1000,750);im.thumbnail((500,375));x=i%3*500;y=55+i//3*415;sheet.paste(im,(x,y+28));d.text((x+12,y),name,font=small,fill='#173F57')
line=Image.open(P/'lineup-three-quarter.png');assert line.size==(1600,1000);line.thumbnail((850,530));sheet.paste(line,(580,1260));d.text((20,1320),'Equal scale, left to right:',font=small,fill='#173F57');d.text((20,1350),'Compact / Jig / Prep',font=font,fill='#173F57');d.text((20,1400),'7.0 m nominal Jig hull',font=small,fill='#173F57');d.text((20,1430),'8 lamps / 3 jig reels',font=small,fill='#173F57');d.text((20,1460),'Clear aft centre deck',font=small,fill='#173F57')
sheet.save(P/'review-sheet.png')
# A separate top-lineup label strip preserves full same-scale image.
for name in ['lineup-top','lineup-three-quarter']:
 im=Image.open(P/(name+'.png')).convert('RGB');out=Image.new('RGB',(1600,1060),'#EDE7DC');out.paste(im,(0,60));dd=ImageDraw.Draw(out);dd.text((20,15),'SAME SCALE: COMPACT (left) / JIG (centre) / PREP (right) — authoring render',font=font,fill='#173F57');out.save(P/(name+'-labelled.png'))
v=json.loads((O/'validation.json').read_text());audit=json.loads((O/'bounds-audit.json').read_text());metrics=json.loads((O/'build-metrics.json').read_text())
report=(O/'REPORT.md').read_text().split('## B. Model')[0]+'''## B. Model — technical checks complete\n\nNew editable JigBoatV1.blend and JigBoatV1.fbx; **%d triangles / 13,000 cap**, %d meshes, 44 total nodes. Eight separately named lamps, three separate jig reels, one lengthwise sagging cable, two short masts, one sorting tray. No net gear or large processing machinery. Small enclosed ivory wheelhouse forward, swept sheer, three shallow clinker laps, orange boot-top, broad timber planks and restrained working fittings.\n\nAuthoring coordinates: X right, -Y bow, Z up; flat deck at Z=0. Nominal shell 7.0×3.3 m; full fittings-inclusive bounds %s to %s metres. Root Catchline_JigBoatV1 at identity. Socket/deck/grid integration is intentionally left to Claude. All current meshes are children of that root.\n\nFBX_SCALE_UNITS export, **raw UnitScaleFactor100**, matching the corrected existing boats; no extra100× root scale. Independent FBX reimport checks every mesh bounds, finite geometry, nonzero face area, parents and original source matrices. Blend/FBX max nearest vertex deviation **%.9g m**. No oversized mesh, presentation floor, camera, light or shadow catcher is exported. The exported FBX is reimported independently to make all renders; the presentation stage exists only after export.\n\nClear central aft walking volume X[-0.80,0.65], Y[-0.95,2.65], Z[0.035,1.7]m checked with polygon/box clipping for EVERY exported face: no intersections. This is geometric authoring clearance, not native crew pathfinding acceptance. Flush hatch/handle stay below0.035m. Wheelhouse side paths remain open. Bulbs use existing M_BandIvory, not new emissive materials; native night-light effects/material setup remain integration scope.\n\n### Every exported mesh — world bounds (metres)\n\n| Mesh | World minimum XYZ | World maximum XYZ | Triangles |\n| --- | --- | --- | ---: |\n'''%(v['triangles'],v['mesh_count'],v['world_min_m'],v['world_max_m'],v['blend_fbx_max_vertex_delta_m'])
f=lambda xyz:'('+', '.join('%.5f'%x for x in xyz)+')'
for r in audit['rows']:report+='| %s | %s | %s | %d |\n'%(r['name'],f(r['world_min_m']),f(r['world_max_m']),r['triangles'])
report+='''\n### Visual evidence\n\n`renders/` contains side, top, front-three-quarter, back-three-quarter, deck-55, low-waterline and game-exact-45, all1000×750, plus same-scale Compact/Jig/Prep lineup top and three-quarter1600×1000; labelled copies and review-sheet.png. Matched house lighting, matte materials, orthographic projection. No original neighbouring boat files are modified. Full visual opening/review status is recorded in comms.md and visual-review.txt after inspection.\n\n### Reproduce\n\nWindows Blender5.2: --background --python Art/Source/BoatsV2/JigBoat/build_jig.py; then review_jig.py. Python/Pillow: finish_jig.py. All steps affect only new Jig-owned paths. LinuxBlender5.0 FBX operator was incompatible with the established export flags; initial failure is retained in build.log, successful Windows run in build-windows.log.\n\n## C. Refit card\nPending B visual review.\n\nNo git, commit, Unity, .cs, .meta or other boat edits. Native import, night lighting, gameplay and pathfinding acceptance are not claimed.\n'''
(O/'REPORT.md').write_text(report)
images={p.name:{'size':Image.open(p).size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in P.glob('*.png')};(S/'image-validation.json').write_text(json.dumps(images,indent=2));print('SHEETS/REPORT PASS',v['triangles'],len(images))
